import React, { useState } from "react";
import costoStandardData from "../costi_standard.json";
import "../styles/forms.css";
import "../styles/tabelle.css";
import "../styles/buttons.css";

export default function ProgrammaEsecutivo() {
  const [selected, setSelected] = useState(null);
  const [descrizione, setDescrizione] = useState("");
  const [tipo, setTipo] = useState("");
  const [quantita, setQuantita] = useState(1);
  const [esecuzione, setEsecuzione] = useState("");
  const [righe, setRighe] = useState([]);

  const currencyFormatter = new Intl.NumberFormat("it-IT", {
    style: "currency",
    currency: "EUR",
  });

  const handleSelect = (code) => {
    const az = costoStandardData.find((a) => a.azioneOperativa === code);
    setSelected(az || null);
    setDescrizione("");
    setTipo("");
    setQuantita(1)
  };

  const calcolaValore = (base) =>
    quantita && !isNaN(quantita) ? base * parseInt(quantita) : 0;
    
  
  const costoTotale =
    (selected ? calcolaValore(selected.personale) : 0) +
    (selected ? calcolaValore(selected.materiali) : 0) +
    (selected ? calcolaValore(selected.carburanti || 0) : 0) +
    (selected ? calcolaValore(selected.noli) : 0);

  const aggiungiRiga = () => {
    if (!selected) return;
    const nuovaRiga = {
      azioneOperativa: selected.azioneOperativa,
      descrizioneIntervento: descrizione,
      tipo,
      um: selected.um,
      quantita,
      esecuzione,
      personale: calcolaValore(selected.personale),
      materiali: calcolaValore(selected.materiali),
      carburanti: calcolaValore(selected.carburanti || 0),
      noli: calcolaValore(selected.noli),
      costoTotale,
    };
    setRighe([...righe, nuovaRiga]);
  };                                                                

  // 🔽 Funzione per salvare i dati su SharePoint
const salvaSuSharePoint = async () => {
  const sito = "https://agenziaforestas.sharepoint.com/sites/ServizioTecnico";
  const lista = "PianificazioneForestaleDati";

  // Crea un oggetto dati da inviare
  const dati = {
    Missione: "Foreste e Ambiente", // puoi sostituire con il valore scelto altrove
    Programma: "Gestione forestale", // idem
    TipoDocumento: "Altro", // o leggi da un menù
    Data: new Date().toISOString(),
    Descrizione: descrizione,
    ObiettivoStrategico: "",
    ObiettivoDirezionale: "",
    ObiettivoGestionale: "",
    CdR: "",
    CodiceSAP: "",
    CostoTotale: costoTotale
  };

  try {
    const response = await fetch(
      `${sito}/_api/web/lists/getbytitle('${lista}')/items`,
      {
        method: "POST",
        headers: {
          "Accept": "application/json;odata=verbose",
          "Content-Type": "application/json;odata=verbose",
          "X-RequestDigest": document.getElementById("__REQUESTDIGEST").value,
        },
        body: JSON.stringify({
          __metadata: { type: `SP.Data.${lista}ListItem` },
          ...dati,
        }),
      }
    );

    if (response.ok) {
      alert("✅ Dati inviati correttamente a SharePoint!");
    } else {
      const err = await response.text();
      console.error(err);
      alert("⚠️ Errore durante il salvataggio su SharePoint.");
    }
  } catch (error) {
    console.error(error);
    alert("❌ Errore di rete o permessi insufficienti.");
  }
};

                                                                
  return (              
    <div>
      <div className="form-group">
        <label className="form-label">Azione Operativa</label>                       
        <select
          className="form-select"
          onChange={(e) => handleSelect(e.target.value)}
          value={selected?.azioneOperativa || ""}
        >
          <option value="">-- Seleziona Azione --</option>
          {costoStandardData.map((a, i) => (
            <option key={i} value={a.azioneOperativa}>
              {a.azioneOperativa} - {a.descrizione}
            </option>
          ))}
        </select>
      </div>

      {selected && (
        <div className="form-section">
          <div className="form-group">
            <label className="form-label">Descrizione sintetica</label>
            <input
              type="text"
              className="form-input"
              value={descrizione}
              onChange={(e) => setDescrizione(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Tipo</label>
            <input
              type="text"
              className="form-input"
              value={tipo}
              onChange={(e) => setTipo(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Quantità ({selected.um})</label>
            <input
              type="number"
              min="1"
              step="1"
              className="form-input"
              value={quantita}
              onChange={(e) => setQuantita(e.target.value)}
            />
          </div>

          <div className="col-md-4 mb-3">
              <label className="form-label fw-semibold">Esecuzione</label>
              <select
                className="form-select"
                value={esecuzione}
                onChange={(e) => setEsecuzione(e.target.value)}>
                <option value="">-- Seleziona esecuzione--</option>
                <option value="Amministrazione Diretta">Amministrazione Diretta</option>
                <option value="Appalto">Appalto</option>
              </select>
        </div>


          <p><strong>Costo Totale:</strong> {currencyFormatter.format(costoTotale)}</p>
          <div>
          <button className="btn" onClick={aggiungiRiga}>
            ➕ Aggiungi alla tabella
          </button>
        </div>

        <button className="btn btn-primary" onClick={salvaSuSharePoint}>
            💾 Salva su SharePoint
        </button>
        </div>
      )}

      
    </div>
  );
}
